exercise.solution:
fn total_saved(days: i32) -> i32 {
    let mut total = 0;
    for day in 1..=days {
        total = total + day;
    }
    total
}

fn stars(total: i32) -> i32 {
    let mut result = 1;
    if total >= 50 {
        result = 3;
    } else if total >= 10 {
        result = 2;
    }
    result
}

fn days_to_reach(goal: i32) -> i32 {
    let mut days = 0;
    let mut total = 0;
    while total < goal {
        days = days + 1;
        total = total + days;
    }
    days
}

fn main() {
    let mut coins = total_saved(0);
    println!("After 0 days: {coins} coins, stars: {}", stars(coins));
    coins = total_saved(4);
    println!("After 4 days: {coins} coins, stars: {}", stars(coins));
    coins = total_saved(10);
    println!("After 10 days: {coins} coins, stars: {}", stars(coins));

    println!("Goal 0 takes {} days", days_to_reach(0));
    println!("Goal 15 takes {} days", days_to_reach(15));
    println!("Goal 20 takes {} days", days_to_reach(20));
}
